function assessmentStep(name){panel("assessment");if(!$("notice").classList.contains("error"))$("notice").hidden=true;window.scrollTo({top:0,behavior:"instant"});document.querySelectorAll('.assessment-step').forEach(node=>node.classList.toggle('active',node.id==='a-'+name));document.querySelectorAll('[data-step]').forEach(node=>node.classList.toggle('selected',node.dataset.step===name));}
