$('a-profile').onchange=()=>{
 aResetImportSelection();aClearImportFiles();const raw=$('a-profile').value===aRawImportProfile;$('a-raw-import').hidden=!raw;$('a-source-origin').required=raw;
 $('a-import-file-label').textContent=raw?'Choose raw request':'Choose request export';$('a-import-file').accept=raw?'.txt,.http,.req,.bin,application/octet-stream,text/plain':'.xml,.json,.har';
};
$('a-source-origin').oninput=()=>{aResetImportSelection();aRawImportMetadata();};
$('a-import-response').onchange=guarded(async()=>{if(aImportBusy)return;aResetImportSelection();try{aRawImportSize();aRawImportMetadata();}catch(error){aClearImportFiles();throw error;}});
$('a-import-file').onchange=guarded(async()=>{
 if(aImportBusy)return;aResetImportSelection();const file=$('a-import-file').files[0];if(!file)return;
 if($('a-profile').value===aRawImportProfile){try{aRawImportSize();aRawImportMetadata();}catch(error){aClearImportFiles();throw error;}return;}
 let text='';aImportPending(true);
 try{if(file.size>3*1024*1024)throw Error('Choose an export smaller than 3 MiB.');text=await file.text();aShowImported(await api('/api/assessment/import',{text,profile:$('a-profile').value}));}
 finally{text='';aClearImportFiles();aImportPending(false);}
});
async function aImportFileBase64(file){
 const bytes=new Uint8Array(await file.arrayBuffer());let binary='';
 try{for(let offset=0;offset<bytes.length;offset+=32768)binary+=String.fromCharCode(...bytes.subarray(offset,offset+32768));return btoa(binary);}
 finally{bytes.fill(0);binary='';}
}
$('a-import-raw').onclick=guarded(async()=>{
 if(aImportBusy)return;let payload={};aImportPending(true);
 try{
  if($('a-profile').value!==aRawImportProfile)throw Error('Choose the Burp raw request / response profile.');
  aRawImportSize();const request=$('a-import-file').files[0],response=$('a-import-response').files[0],sourceOrigin=$('a-source-origin').value.trim();
  if(!request)throw Error('Choose a saved raw HTTP request.');if(!sourceOrigin)throw Error('Enter the capture source origin.');
  payload={profile:aRawImportProfile,source_origin:sourceOrigin,request_base64:await aImportFileBase64(request)};
  if(response)payload.response_base64=await aImportFileBase64(response);
  aShowImported(await api('/api/assessment/import',payload));
 }finally{payload.request_base64='';payload.response_base64='';aClearImportFiles();aImportPending(false);}
});
async function aBindings(){
 const owner=$('a-owner').value.trim(),actor=$('a-actor').value.trim();if(!owner||!actor||owner===actor)throw Error('Choose two distinct identity names.');
 const marker=await aTypedValue('a-rule-value','a-rule-value-type'),principalPointer=$('a-identity-pointer').value.trim(),principal=$('a-identity-value').value;
 const bindings={id:'assessment-experiment',title:$('a-title').value.trim(),target:$('a-target').value.trim(),identities:{[owner]:{headers:{[$('a-credential-header').value]:{env:$('a-owner-ref').value.trim()}}},[actor]:{headers:{[$('a-credential-header').value]:{env:$('a-actor-ref').value.trim()}}}},owner_identity:owner,actor_identity:actor,identity_probe:{path:$('a-identity-path').value.trim(),expect:{status:[200],json:{[principalPointer]:principal}}},negative_probe:{path:$('a-negative-path').value.trim(),expect:{status:$('a-negative-status').value.split(',').map(s=>Number(s.trim())),json_absent:[$('a-rule-pointer').value.trim()]}},rule:{id:'protected-content-boundary',kind:'forbid_field_equal',pointer:$('a-rule-pointer').value.trim(),value:marker,resource_id:$('a-resource').value.trim()},capture_mode:$('a-capture').value,identity_bindings:{[actor]:{principal_pointer:principalPointer,principal}},limits:{max_requests:Number($('a-experiment-budget').value),timeout_seconds:Number($('a-experiment-timeout').value),concurrency:Number($('a-experiment-concurrency').value)},omitted_secret_slots:[...$('a-import-mappings').querySelectorAll('[data-header-slot]:checked')].map(input=>input.dataset.headerSlot)};
 const tenantPointer=$('a-tenant-pointer').value.trim(),tenant=$('a-tenant-value').value;if(tenantPointer||tenant){if(!tenantPointer||!tenant)throw Error('Supply both tenant pointer and expected marker.');bindings.identity_probe.expect.json[tenantPointer]=tenant;Object.assign(bindings.identity_bindings[actor],{tenant_pointer:tenantPointer,tenant});}
 if($('a-owner-path').value.trim())bindings.owner_probe={path:$('a-owner-path').value.trim(),expect:{status:[200],json:{[bindings.rule.pointer]:marker}}};
 if($('a-resource-pointer').value.trim())Object.assign(bindings.rule,{resource_pointer:$('a-resource-pointer').value.trim(),resource_value:await aTypedValue('a-resource-value','a-resource-value-type')});
 bindings.selected_variants=[];for(const variant of assessment.variantDrafts||[]){const selection={id:variant.id.trim(),identity:actor,path:variant.path.trim(),method:variant.method};if(variant.headers.trim())selection.headers=aPublicHeaders(variant.headers);if(variant.body.trim())selection.body=await strictJSON(variant.body);bindings.selected_variants.push(selection);}
 if(!bindings.selected_variants.length)throw Error('Choose at least one explicit variant.');
 const mutations=bindings.selected_variants.filter(v=>!['GET','HEAD','OPTIONS'].includes(v.method)).map(v=>'variant-'+v.id);if(mutations.length&&!$('a-mutation-approval').checked)throw Error('Review the mutating variants and enable their explicit plan inclusion.');bindings.mutation_approval=mutations;const imported=assessment.imported?.entries[assessment.entryIndex],single=assessment.variantDrafts?.[0];if(bindings.selected_variants.length===1&&single.id==='cross-identity'&&single.path===imported?.path&&single.method===imported?.method&&!single.headers.trim()&&!single.body.trim())delete bindings.selected_variants;return bindings;
}
function aClearCredentialDrafts(){for(const role of ['owner','actor'])$('a-'+role+'-secret').value='';}
async function aCredentials(){
 const revision=assessment.revision,origin=$('a-target').value.trim(),bindings=['owner','actor'].map(role=>({env:$('a-'+role+'-ref').value.trim(),value:$('a-'+role+'-secret').value,identity:$('a-'+role).value.trim(),target_origin:origin}));aClearCredentialDrafts();
 try{for(const binding of bindings){if(assessment.revision!==revision)throw Error('Credential bindings changed during preparation. Review the current origin and identities again.');if(binding.value)await api('/api/assessment/credentials',binding);if(assessment.revision!==revision)throw Error('Credential bindings changed during preparation. Review the current origin and identities again.');}}
 finally{for(const binding of bindings)binding.value='';}
}
function aPresentPlan(result,kind='experiment'){assessment.plan=result.plan;assessment.review=result.review;assessment.kind=kind;$('a-authorized').checked=false;$('a-run').disabled=true;$('a-run').textContent=kind==='experiment'?'Run experiment':kind==='reduction'?'Run reviewed reduction':kind==='workflow-assurance'?'Run bounded workflow assurance':'Run reviewed workflow';$('a-plan-card').hidden=false;const contract=result.plan.contract||result.plan.spec?.contract||result.plan.workflow_plan?.spec?.contract||result.plan.execution?.contract||result.plan.original_execution?.contract||result.plan.original_execution?.plan?.spec?.contract;const cases=contract?.cases||[];$('a-plan-budget').textContent=(result.plan.max_requests||result.plan.spec?.max_requests_total||result.plan.request_upper_bound||cases.length)+' request budget';$('a-plan-target').textContent='Authorized origin under review: '+(contract?.target||result.plan.scope?.target||'Unavailable');$('a-plan-rows').replaceChildren();for(const c of cases){const row=element('div',undefined,'assessment-row'),text=element('div');text.append(element('strong',c.method+' '+c.path),element('small',c.id+' · '+c.identity+' · controls: '+(c.requires?.join(', ')||'none')));row.append(text);$('a-plan-rows').append(row);}if(kind==='workflow-assurance')$('a-plan-rows').append(element('p',result.plan.spec.max_cycles+' maximum cycles · '+result.plan.cycle_request_upper_bound+' requests per cycle · '+result.plan.cleanup_reserve+' cleanup requests reserved · '+(result.history_storage==='persistent'?'Durable history':'Session-only history: lost when Studio closes')+' · Stop on violation or uncertainty.','subtle'));if(!cases.length)$('a-plan-rows').append(element('pre',pretty(result.plan),'assessment-plan-json'));$('a-plan-hash').textContent='Plan · '+(result.plan.plan_digest||result.plan.experiment_digest||result.plan.plan_sha256||'Bound to this session review');$('a-experiment-save').disabled=!result.plan.spec||result.plan.kind!=='experiment-plan';aContext();assessmentStep('contrast');$('a-plan-card').scrollIntoView({block:'nearest'});aInspect('Reviewed '+kind,'No target requests sent during preview',{Target:contract?.target||$('a-target').value,'Request budget':$('a-plan-budget').textContent,'Plan digest':$('a-plan-hash').textContent,Controls:'Every prerequisite remains in the reviewed plan',Authorization:'Waiting for your explicit approval','Data gaps':'The preview does not establish execution truth.'});}
$('a-preview').onclick=guarded(async()=>{if(assessment.entryIndex===null)throw Error('Import and select a request first.');const revision=assessment.revision;await aCredentials();const bindings=await aBindings();if(assessment.revision!==revision)throw Error('The draft changed during preparation. Preview the current scope again.');await aPreviewService('/api/assessment/plan',{import_id:assessment.importId,entry_index:assessment.entryIndex,bindings,mappings:aMappings()});});
