function aWorkflowRow(role,method,path,status,expected=''){const row={role,method,path,status,expected,identity:['setup','cleanup'].includes(role)?'owner':'actor',headers:'',body:''};workflowRows.push(row);aRenderWorkflow();}
function aRenderWorkflow(){
 $('a-workflow-steps').replaceChildren();workflowRows.forEach((row,index)=>{const node=element('div',undefined,'workflow-step');node.dataset.stepIndex=index;
 for(const [key,label] of [['role','Purpose'],['method','Method'],['path','Path'],['status','Expected HTTP'],['expected','Expected JSON pointer values (optional)']]){const field=element('label',label);let input;if(key==='role'||key==='method'){input=element('select');for(const kind of key==='role'?['control','setup','precondition','step','postcondition','cleanup']:['GET','HEAD','OPTIONS','POST','PUT','PATCH','DELETE']){const option=element('option',kind);option.value=kind;input.append(option);}}else input=element('input');input.value=row[key];input.dataset.field=key;input.oninput=()=>{row[key]=input.value;};field.append(input);node.append(field);}
 const extra=element('details',undefined,'workflow-step-extra');extra.append(element('summary','Identity, public headers and request body'));const grid=element('div',undefined,'form-grid');for(const [key,label] of [['identity','Step identity'],['headers','Public headers · one Name: value per line'],['body','JSON body (optional)']]){const field=element('label',label);let input;if(key==='identity'){input=element('select');for(const [value,title] of [['owner','Owner identity'],['actor','Testing identity']]){const option=element('option',title);option.value=value;input.append(option);}}else{input=element('textarea');input.rows=3;input.spellcheck=false;}input.dataset.field=key;input.value=row[key];input.oninput=()=>row[key]=input.value;field.append(input);grid.append(field);}extra.append(grid);node.append(extra);const remove=element('button','Remove step');remove.onclick=()=>{workflowRows.splice(index,1);aInvalidate();aRenderWorkflow();};node.append(remove);$('a-workflow-steps').append(node);});
}
