$('a-workflow-add').onclick=()=>{aWorkflowRow('step','POST','/jobs/object/approve','200','');aInvalidate();};
async function aWorkflowSpec(){const advanced=$('a-workflow-json').value.trim();if($('a-workflow-source').value==='spec'){if(!advanced)throw Error('Import or enter a workflow specification first.');return strictJSON(advanced);}const owner=$('a-owner').value.trim(),actor=$('a-actor').value.trim(),cases=[],roles={control:[],setup:[],precondition:[],step:[],postcondition:[],cleanup:[]};for(const [index,row] of workflowRows.entries()){const id=row.role+'-'+index,expect={status:row.status.split(',').map(s=>Number(s.trim()))};if(row.expected.trim())expect.json=await strictJSON(row.expected);const operation={id,identity:row.identity==='owner'?owner:actor,method:row.method.toUpperCase(),path:row.path,expect};if(row.headers.trim())operation.headers=aPublicHeaders(row.headers,true);if(row.body.trim())operation.body=await strictJSON(row.body);cases.push(operation);roles[row.role].push({id,case_id:id,bindings:[]});}for(const role of ['setup','precondition','postcondition'])if(roles[role].length!==1)throw Error('Exactly one '+role+' operation is required.');for(const step of [...roles.precondition,...roles.step,...roles.postcondition,...roles.cleanup])step.bindings=[{source_step:roles.setup[0].id,pointer:$('a-workflow-fixture-pointer').value,type:'string',target:{kind:'path_segment',index:Number($('a-workflow-path-index').value)}}];const variant={id:'reviewed-sequence',omit:[],identity_overrides:{},repeat:{}};const choice=$('a-workflow-variant').value;if(choice==='replay'&&roles.step.length)variant.repeat[roles.step.at(-1).id]=2;if(choice==='skip'&&roles.step.length)variant.omit=[roles.step[0].id];return {schema_version:1,kind:'workflow-spec',id:'studio-workflow',title:$('a-workflow-title').value,contract:{version:1,name:$('a-workflow-title').value,target:$('a-target').value,identities:{[owner]:{headers:{[$('a-credential-header').value]:{env:$('a-owner-ref').value}}},[actor]:{headers:{[$('a-credential-header').value]:{env:$('a-actor-ref').value}}}},cases},controls:roles.control.map(s=>s.case_id),setup:roles.setup[0],precondition:roles.precondition[0],steps:roles.step,postcondition:roles.postcondition[0],cleanup:roles.cleanup,fixture:{source_step:roles.setup[0].id,pointer:$('a-workflow-fixture-pointer').value,type:'string',read_pointer:$('a-workflow-fixture-pointer').value},rule:$('a-workflow-rule').value==='effect_increase'?{id:'effect-boundary',kind:'effect_increase',pointer:$('a-workflow-state-pointer').value,max_delta:Number($('a-workflow-max-delta').value)}:{id:'forbidden-transition',kind:'forbidden_state',pointer:$('a-workflow-state-pointer').value,value:await aTypedValue('a-workflow-state-value','a-workflow-value-type')},variants:[variant],mutation_approval:cases.filter(c=>!['GET','HEAD','OPTIONS'].includes(c.method)).map(c=>c.id)};}
