function aImportMappings(entry){const node=$('a-import-mappings');node.replaceChildren();for(const slot of entry.secret_slots){if(/authorization|cookie/i.test(slot.location))continue;const row=element('div',undefined,'assessment-row'),label=element('label',slot.location+' · '+slot.kind);if(slot.kind==='header'){const input=element('input');input.type='checkbox';input.dataset.headerSlot=slot.id;label.append(input,document.createTextNode(' Explicitly omit this imported header'));}else{const input=element('input');input.dataset.mappingSlot=slot.id;input.placeholder='Explicit public replacement value';const omit=element('input');omit.type='checkbox';omit.dataset.mappingOmit=slot.id;label.append(input,omit,document.createTextNode(' Omit this field'));}row.append(label);node.append(row);}}
function aMappings(){const output={};for(const input of $('a-import-mappings').querySelectorAll('[data-mapping-slot]')){const omit=[...$('a-import-mappings').querySelectorAll('[data-mapping-omit]')].find(check=>check.dataset.mappingOmit===input.dataset.mappingSlot);if(omit.checked)output[input.dataset.mappingSlot]={omit:true};else if(input.value)output[input.dataset.mappingSlot]={literal:input.value};}return output;}
function aRenderTrace(destination,trace){
 const target=$(destination),container=element('div',undefined,'assessment-trace');target.replaceChildren(container);
 if(trace.kind==='workflow-assurance-result'){
  container.append(element('h3','Bounded workflow assurance · '+trace.status),element('p',trace.completed_cycles+' completed cycles · '+trace.budget_ledger.dispatched_total+' requests · '+trace.stop_reason,'subtle'));
  for(const cycle of trace.cycles){const row=element('div',undefined,'assessment-row'),detail=element('div');detail.append(element('strong','Cycle '+cycle.cycle+' · '+cycle.status),element('small',cycle.stop_reason||'All reviewed controls and cleanup satisfied'),element('small','History anchor: '+(cycle.history?.record_sha256||'Not retained')));for(const variant of cycle.trace.variants||[])detail.append(element('small',variant.id+' · '+variant.interpretation+' · controls '+(variant.controls_valid?'valid':'invalid')+' · cleanup '+variant.cleanup));row.append(detail);container.append(row);}
 }else if(trace.kind==='reduction-trace'){
  container.append(element('h3',trace.label||'Reduction evidence'),element('p',(trace.accepted_removed?.length||0)+' accepted removals · '+trace.requests_used+' requests · '+trace.stop_reason,'subtle'));
  const accepted=trace.accepted_execution,original=trace.original_execution;container.append(element('p','Original: '+(original.execution_digest||original.workflow_digest)+' · Retained reproduction: '+(accepted.execution_digest||accepted.workflow_digest),'anchor'));
  for(const index of trace.accepted_removed||[])container.append(element('div','Removed: '+aUnitText(trace.plan.units[index]),'assessment-row'));
  const contract=accepted.contract||accepted.plan?.spec?.contract,controlled=new Set(trace.plan.units.map(unit=>unit.case_id));for(const operation of contract?.cases||[])if(controlled.has(operation.id)){const row=element('div',undefined,'assessment-row'),detail=element('div');detail.append(element('strong','Reproducer · '+operation.method+' '+operation.path),element('small','Identity reference: '+operation.identity+' · case '+operation.id));row.append(detail);container.append(row);}
  for(const [index,attempt] of (trace.attempts||[]).entries()){const execution=attempt.execution,controls=execution.findings?.[0]?.control_refs||execution.variants?.[0]?.controls||[],row=element('button',undefined,'assessment-row'),detail=element('div');detail.append(element('strong','Attempt '+(index+1)+' · '+attempt.interpretation),element('small',attempt.phase+' · removal candidates: '+attempt.removed.map(i=>aUnitText(trace.plan.units[i])).join('; ')),element('small','Evidence: '+(execution.execution_digest||execution.workflow_digest)));row.append(detail);row.onclick=()=>aInspect('Reduction attempt '+(index+1),attempt.interpretation,{Phase:attempt.phase,'Removed candidates':attempt.removed.map(i=>aUnitText(trace.plan.units[i])),Controls:controls,Findings:execution.findings||execution.variants,Root:execution.report?.evidence?.root_sha256||execution.workflow_digest,Scope:execution.contract?.target||execution.plan?.spec?.contract?.target});container.append(row);}
 }else{for(const variant of trace.variants||[]){const row=element('div',undefined,'assessment-row'),detail=element('div');detail.append(element('strong',variant.id+' · '+variant.interpretation),element('small','Controls: '+(variant.controls_valid?'valid':'invalid')+' · cleanup: '+variant.cleanup),element('small',variant.reason||''));row.append(detail);container.append(row);}}
 const save=element('button',trace.kind==='reduction-trace'?'Export reproducer evidence':'Export workflow evidence');save.onclick=()=>download(trace,trace.kind==='reduction-trace'?'authzledger-reproducer.json':'authzledger-workflow.json');container.append(save);const details=element('details'),summary=element('summary','Inspect complete trace'),pre=element('pre',pretty(trace));details.append(summary,pre);container.append(details);
}
function aReportMetadata(){const metadata={assessment_id:'local-assessment',title:$('a-title').value,finding_annotations:assessment.annotations};if($('a-reviewer').value.trim())metadata.reviewer=$('a-reviewer').value.trim();if($('a-summary').value.trim())metadata.executive_summary=$('a-summary').value.trim();return metadata;}
function aLoadAnnotation(finding){$('a-annotation-selection').textContent=finding.id+' · '+finding.identity+' → '+finding.resource_id;const annotation=assessment.annotations[finding.id]||{};for(const [key,id] of [['impact','a-impact'],['remediation','a-remediation'],['business_risk','a-business-risk'],['cvss_vector','a-cvss']])$(id).value=annotation[key]||'';const ref=annotation.standard_refs?.[0];$('a-standard').value=ref?ref.standard+'|'+ref.version+'|'+ref.id:'';$('a-standard-rationale').value=ref?.rationale||'';for(const [id,value] of Object.entries(assessment.annotationDrafts?.[finding.id]||{}))$(id).value=value;}
$('a-annotation-save').onclick=guarded(async()=>{const finding=assessment.current?.value.findings[assessment.selected];if(!finding)throw Error('Select a finding before writing its impact and remediation.');const annotation={};for(const [key,id] of [['impact','a-impact'],['remediation','a-remediation'],['business_risk','a-business-risk'],['cvss_vector','a-cvss']])if($(id).value.trim())annotation[key]=$(id).value.trim();if($('a-standard').value){const [standard,version,id]=$('a-standard').value.split('|');if(!$('a-standard-rationale').value.trim())throw Error('Explain how the finding evidence relates to the selected standard.');annotation.standard_refs=[{standard,version,id,relation:'related',rationale:$('a-standard-rationale').value.trim(),evidence_refs:finding.evidence_refs}];}assessment.annotations[finding.id]=annotation;if(assessment.annotationDrafts)delete assessment.annotationDrafts[finding.id];aSnapshotDirty('Finding details changed. Freeze a new assessment to include them.');notify('Finding annotation saved. Freeze a new assessment to include it.');});
