$('a-impact-preview').onclick=guarded(async()=>{if(!assessment.current)throw Error('Run an experiment before planning its impacted retest.');aInvalidate();const revision=assessment.revision,source=assessment.current;const changes=[{kind:$('a-change-kind').value,id:$('a-change-id').value.trim(),before_digest:$('a-change-before').value.trim()||null,after_digest:$('a-change-after').value.trim()||null}],impact_map=$('a-impact-map').value.trim()?await strictJSON($('a-impact-map').value):{};if(assessment.revision!==revision||assessment.current!==source)throw Error('The draft changed during impact preparation. Preview the current baseline again.');const result=await api('/api/assessment/impact',{execution_id:source.id,changes,impact_map});if(assessment.revision!==revision||assessment.current!==source)throw Error('The draft changed during impact preview. Review the current baseline again.');$('a-impact-result').replaceChildren();for(const [id,reasons] of Object.entries(result.impact.reasons))$('a-impact-result').append(element('div',id+' · '+reasons.map(reason=>reason.reason_code+' ('+reason.source_refs.join(', ')+')').join('; '),'assessment-row'));if(result.plan){aPresentPlan(result);$('a-plan-rows').append(element('p','Selection cause: '+(result.impact.unknown_dependencies.length?'Unknown dependencies → full approved scope':changes[0].kind+' change')+' · Not retested: '+(result.impact.not_retested_ids.join(', ')||'none'),'subtle'));}else notify('No changed dependency requires another request. All cases remain not_retested.');});

