function aRestoreContext(execution){if($('a-title').value!==execution.plan.spec.title)aSnapshotDirty('Selected evidence changed the assessment title. Freeze the updated report details before export.');if($('a-target').value!==execution.contract.target)aClearCredentialDrafts();$('a-title').value=execution.plan.spec.title;$('a-target').value=execution.contract.target;$('a-rule-pointer').value=execution.plan.rule.pointer||'';$('a-rule-value').value=typeof execution.plan.rule.value==='string'?execution.plan.rule.value:JSON.stringify(execution.plan.rule.value??null);$('a-rule-value-type').value=typeof execution.plan.rule.value==='string'?'string':'json';$('a-resource').value=execution.plan.rule.resource_id||'';aContext();}
function aRecovery(jobs){if(!jobs.length)return;const node=$('a-recovery');node.hidden=false;node.replaceChildren(element('h3','Resume retained work'),element('p','Reconnect to an existing job. No request is repeated and no new execution is started.','subtle'));for(const job of jobs){const button=element('button',job.kind+' · '+job.state,'assessment-row');button.dataset.kind=job.kind;button.dataset.jobId=job.id;button.onclick=guarded(async()=>{const result=await api('/api/assessment/recover',{job_id:job.id});if(result.baseline_execution&&!assessment.executions.some(e=>e.id===result.baseline_execution.id))assessment.executions.push(result.baseline_execution);await aWatch(result.job);node.hidden=true;});node.append(button);}}

function aRetestText(transition,envelope){if(!transition)return "Not retested";const historical=envelope.baseline_report.finished_at,current=envelope.current_report.finished_at;return transition.status==="not_retested"?"not_retested · historical evidence: "+historical:transition.status+" · baseline: "+historical+" → retest: "+current;}

function aRetestTransitions(){return (assessment.comparison?.transitions||[]).map(item=>({...item,status:assessment.findingComparison?.transitions.find(finding=>finding.case_id===item.case_id)?.status||item.status}));}

// Explicit graphical drafts; server compilers remain the authority for every plan.
async function aTypedValue(valueId,typeId){return $(typeId).value==='json'?strictJSON($(valueId).value):$(valueId).value;}
function aPublicHeaders(text,workflow=false){
 const headers={},names=new Set();for(const line of text.split(/\r?\n/)){if(!line.trim())continue;const colon=line.indexOf(':');if(colon<1)throw Error('Public headers use one Name: value per line.');const name=line.slice(0,colon).trim(),lower=name.toLowerCase();if(names.has(lower))throw Error('Duplicate header names need an explicitly supported source profile.');if(/authorization|cookie|token|secret|credential|api.?key|session/i.test(name))throw Error('Bind credential headers through identity references, not literal request fields.');if(!['accept','accept-language','content-type','user-agent','cache-control','pragma','x-request-id','x-correlation-id',...(workflow?['idempotency-key']:[])].includes(lower))throw Error('Choose a supported public request header: Accept, Accept-Language, Content-Type, User-Agent, Cache-Control, Pragma, X-Request-ID, X-Correlation-ID or Idempotency-Key.');names.add(lower);headers[name]=line.slice(colon+1).trim();}return headers;
}
function aSeedVariants(entry){assessment.variantDrafts=[{id:'cross-identity',method:entry.method,path:entry.path,headers:'',body:''}];$('a-mutation-approval').checked=false;$('a-owner-path').value='';$('a-resource-pointer').value='';$('a-resource-value').value='';aRenderVariants();}
function aRenderVariants(){
 const node=$('a-variants');node.replaceChildren();for(const [index,variant] of (assessment.variantDrafts||[]).entries()){
  const card=element('div',undefined,'assessment-variant'),grid=element('div',undefined,'form-grid assessment-variant-fields');
  for(const [key,label] of [['id','Stable variant ID'],['method','Method'],['path','Exact path and query'],['headers','Public header overrides · Name: value'],['body','JSON body override']]){const field=element('label',label);let input;if(key==='method'){input=element('select');for(const method of ['GET','HEAD','OPTIONS','POST','PUT','PATCH','DELETE']){const option=element('option',method);option.value=method;input.append(option);}}else if(key==='headers'||key==='body'){input=element('textarea');input.rows=2;input.spellcheck=false;}else input=element('input');input.value=variant[key];input.dataset.variantField=key;input.oninput=()=>variant[key]=input.value;field.append(input);grid.append(field);}
  card.append(element('strong','Variant '+(index+1)+' · testing identity'),grid);const remove=element('button','Remove variant');remove.disabled=assessment.variantDrafts.length===1;remove.onclick=()=>{assessment.variantDrafts.splice(index,1);aInvalidate();aRenderVariants();};card.append(remove);node.append(card);
 }$('a-variant-add').disabled=!assessment.entryIndex&&assessment.entryIndex!==0||(assessment.variantDrafts?.length||0)>=24;
}
$('a-variant-add').onclick=()=>{if(!assessment.variantDrafts?.length)return;const source=assessment.variantDrafts[0];let sequence=assessment.variantDrafts.length+1;while(assessment.variantDrafts.some(v=>v.id==='variant-'+sequence))sequence++;assessment.variantDrafts.push({...source,id:'variant-'+sequence});aInvalidate();aRenderVariants();};
