$('a-execution-selection').onchange=()=>{const current=assessment.executions.find(e=>e.id===$('a-execution-selection').value);if(!current)return;aInvalidate();assessment.current=current;assessment.selected=null;assessment.retestIds=new Set();assessment.comparison=current.comparison||null;assessment.findingComparison=current.findingComparison||null;aRestoreContext(current.value);aRenderFindings();$('a-retest-result').replaceChildren();for(const transition of aRetestTransitions())$('a-retest-result').append(element('div',transition.case_id+' · '+aRetestText(transition,assessment.comparison),'assessment-row'));};
