async function aOpenReduction(source,label){
 aInvalidate();assessment.reductionSource=null;assessment.units=[];$('a-reduction-preview').disabled=true;$('a-reduction-units').replaceChildren();const revision=assessment.revision,data=await api('/api/assessment/reduction/units',source);if(assessment.revision!==revision)throw Error('The selected baseline changed. Open its reduction again.');assessment.units=data.units;assessment.reductionSource=source;$('a-reduction-source').textContent='Original baseline: '+label;$('a-reduction-units').replaceChildren();
 for(const [index,unit] of data.units.entries()){const row=element('label',undefined,'assessment-row'),input=element('input');input.type='checkbox';input.value=index;input.checked=true;row.append(input,element('span',aUnitText(unit)));$('a-reduction-units').append(row);}
 if(!data.units.length)$('a-reduction-units').textContent='No permitted removable units. The original request has no supported removable fields.';$('a-reduction-preview').disabled=!data.units.length;assessmentStep('reduce');
}
function aWorkflowReducible(trace){const variants=trace.variants||[];return variants.length===1&&variants[0].interpretation==='violation'&&variants[0].controls_valid&&variants[0].cleanup==='complete';}
$('a-workflow-reduce').onclick=guarded(async()=>{const trace=assessment.workflowTrace;if(!trace||!aWorkflowReducible(trace.value))throw Error('Select one confirmed isolated workflow with completed cleanup.');await aOpenReduction({trace_id:trace.id},trace.value.plan.spec.title+' · '+trace.value.workflow_digest);});
$('a-workflow-bindings').onclick=()=>assessmentStep('contrast');
$('a-reduce').addEventListener('input',aInvalidate);
function aSnapshotDirty(message='Report details changed. Freeze a new snapshot before export.'){
 assessment.snapshotRevision=(assessment.snapshotRevision||0)+1;assessment.snapshot=null;for(const id of ['a-json','a-html','a-pdf','a-proof'])$(id).disabled=true;$('a-snapshot-state').textContent=message;$('a-assessment-anchor').textContent='';
}
for(const id of ['a-reviewer','a-summary','a-title'])$(id).addEventListener('input',()=>aSnapshotDirty());
function aSignerFingerprint(data){const fingerprint=data.public_key_sha256||data.signing_public_key_sha256;if(fingerprint)$('a-signer-fingerprint').textContent='Ed25519 public key · SHA-256 of DER SubjectPublicKeyInfo: '+fingerprint;}
function aUnitText(unit){return unit.kind+' · '+(unit.name||unit.pointer)+' · '+unit.case_id+(unit.kind==='query'?' · occurrence '+unit.occurrence:'');}
aContext();

if(matchMedia('(max-width: 800px)').matches&&!$('a-inspector-disclosure').dataset.populated)$('a-inspector-disclosure').open=false;
matchMedia('(max-width: 800px)').addEventListener('change',event=>{if(!$('a-inspector-disclosure').dataset.populated)$('a-inspector-disclosure').open=!event.matches;});

const aAnnotationFields=['a-impact','a-remediation','a-business-risk','a-cvss','a-standard','a-standard-rationale'];
for(const id of aAnnotationFields)$(id).addEventListener('input',()=>{const finding=assessment.current?.value.findings[assessment.selected];if(!finding)return;assessment.annotationDrafts??={};assessment.annotationDrafts[finding.id]=Object.fromEntries(aAnnotationFields.map(id=>[id,$(id).value]));aSnapshotDirty('Unsaved finding details. Save each edited annotation, then freeze a new snapshot.');});

for(const id of ['a-target','a-owner','a-actor','a-owner-ref','a-actor-ref','a-credential-header'])$(id).addEventListener('input',aClearCredentialDrafts);
for(const id of ['a-change-kind','a-change-id','a-change-before','a-change-after','a-impact-map'])$(id).addEventListener('input',aInvalidate);
